if ($input.all().length !== 1) throw new Error('Esperado um evento Telegram por execução.');
const event = $input.item.json;
// Altere somente esta URL. n8n Cloud precisa de HTTPS acessível; localhost aponta para o próprio n8n.
const workerBaseUrl = 'http://host.docker.internal:8787';
return [{ json: { event, workerBaseUrl } }];

const raw = $input.item.json;
const job = $('Worker — autorizar e recuperar job').item.json;
return [{json: {...raw, jobId: job.jobId, chatId: job.chatId, stage: 'preflight', state: raw.state || 'failed', message: typeof raw.message === 'string' ? raw.message : 'Falha de comunicação com o worker. Use /retomar ' + job.jobId + ' após verificar a conexão.'}}];

